-- ============================================================================
-- TABLE: TRACTS
-- ============================================================================

CREATE TABLE `tracts` (
  `id` varchar(36) NOT NULL,
  `state` varchar(2) NOT NULL,
  `county` varchar(100) NOT NULL,
  `tract_name` varchar(255) NOT NULL,
  `legal_description` text,
  `str` varchar(50) DEFAULT NULL,
  `abstract_number` varchar(50) DEFAULT NULL,
  `anum` varchar(50) DEFAULT NULL,
  `gross_acres` decimal(10,2) NOT NULL,
  `royalty` decimal(5,4) DEFAULT NULL,
  `net_mineral_acres` decimal(10,2) DEFAULT NULL,
  `nra` decimal(10,2) DEFAULT NULL,
  `ownership_percentage` decimal(5,2) DEFAULT NULL,
  `title_status` enum('Verified','In Progress','Failed','Verified with Curative Requirements','Unmapped') NOT NULL DEFAULT 'Unmapped',
  `assigned_buyer_id` varchar(36) DEFAULT NULL,
  `nra_cap_usd` decimal(12,2) DEFAULT NULL,
  `source_channel` varchar(100) DEFAULT NULL,
  `routing_notes` text,
  `held_by_fund` tinyint(1) DEFAULT '0',
  `is_locked` tinyint(1) DEFAULT '0',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_tracts_state_county` (`state`,`county`),
  KEY `idx_tracts_assigned_buyer` (`assigned_buyer_id`),
  KEY `idx_tracts_title_status` (`title_status`),
  KEY `idx_tracts_held_by_fund` (`held_by_fund`),
  CONSTRAINT `tracts_ibfk_1` FOREIGN KEY (`assigned_buyer_id`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

